    expect(MARKDOWN_POLICY.rawHtml).toBe(false)
  })

  it('ships no syntax highlighter — a styled <pre><code> in the mono face is enough', () => {
    expect(MARKDOWN_POLICY.syntaxHighlighting).toBe(false)
  })
})

