+/* ============================================================================
+   MARKDOWN — the shared <Markdown> component (decision #3)
+   Every agent-authored prose surface renders through `.md`. Self-sufficient on
+   purpose: it sets its own face and white-space so it reads the same inside a
+   mono, pre-wrap container as it does anywhere else.
+   ========================================================================== */
+.md {
+  font-family: var(--sans);
+  font-size: 11.5px;
+  line-height: 1.55;
+  color: var(--text-2);
+  white-space: normal;
+}
+.md > *:first-child { margin-top: 0; }
+.md > *:last-child { margin-bottom: 0; }
+.md h1, .md h2, .md h3 { color: var(--text); font-weight: 600; line-height: 1.3; margin: 12px 0 5px; }
+.md h1 { font-size: 14px; letter-spacing: -0.01em; }
+.md h2 { font-size: 12.5px; }
+.md h3 { font-size: 11.5px; color: var(--text-2); }
+.md p { margin: 0 0 7px; }
+.md ul, .md ol { margin: 0 0 7px; padding-left: 17px; }
+.md li { margin-bottom: 2.5px; }
+.md li::marker { color: var(--text-4); }
+.md strong { color: var(--text); font-weight: 600; }
+.md em { color: var(--text-2); }
+.md a { color: var(--accent-hi); text-decoration: none; border-bottom: 1px solid var(--accent-line); }
+.md code {
+  font-family: var(--mono);
+  font-size: 10.5px;
+  background: var(--panel-inset);
+  border: 1px solid var(--hairline-soft);
+  border-radius: 3px;
+  padding: 0.5px 4px;
+  color: var(--accent-hi);
+}
+.md pre {
+  background: var(--panel-inset);
+  border: 1px solid var(--hairline-soft);
+  border-radius: var(--radius-sm);
+  padding: 8px 10px;
+  overflow-x: auto;
+  margin: 0 0 8px;
+}
+.md pre code { background: none; border: 0; padding: 0; color: var(--text-2); font-size: 10.5px; }
+.md blockquote {
+  margin: 0 0 8px;
+  padding-left: 10px;
+  border-left: 2px solid var(--accent-line);
+  color: var(--text-3);
+}
+.md table { border-collapse: collapse; width: 100%; margin: 0 0 8px; font-size: 11px; }
+.md th, .md td { border: 1px solid var(--hairline); padding: 4px 7px; text-align: left; }
+.md th { background: var(--panel); color: var(--text-2); font-weight: 600; }
+.md hr { border: 0; border-top: 1px solid var(--hairline); margin: 10px 0; }
+/* GFM task lists — remark-gfm tags the list itself; the marker is the checkbox. */
+.md .contains-task-list { list-style: none; padding-left: 2px; }
+.md input[type="checkbox"] { accent-color: var(--accent); margin-right: 5px; vertical-align: -1px; }
+
